CREATE FUNCTION public.reserve_free_ai_request(p_user_id uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_day date := (now() AT TIME ZONE 'UTC')::date;
  v_attempts integer;
  v_id uuid;
BEGIN
  INSERT INTO public.ai_daily_budget(day) VALUES(v_day) ON CONFLICT DO NOTHING;
  SELECT attempts INTO v_attempts FROM public.ai_daily_budget WHERE day=v_day FOR UPDATE;
  IF v_attempts >= 100 THEN RETURN NULL; END IF;
  v_id := public.reserve_ai_request_v2(p_user_id, to_char(v_day,'YYYY-MM-DD'), 3);
  IF v_id IS NULL THEN RETURN NULL; END IF;
  UPDATE public.ai_daily_budget SET attempts=attempts+1 WHERE day=v_day;
  RETURN v_id;
END;
$$

CREATE OR REPLACE FUNCTION public.join_room_atomic(p_room_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_max int;
  v_status text;
  v_host uuid;
  v_expires_at timestamptz;
  v_count int;
BEGIN
  IF v_uid IS NULL THEN RETURN 'unauthenticated'; END IF;

  SELECT max_members, status, host_user_id, expires_at
    INTO v_max, v_status, v_host, v_expires_at
    FROM public.study_rooms
   WHERE id = p_room_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN 'not_found'; END IF;
  IF v_status <> 'active' THEN RETURN 'closed'; END IF;
  IF v_expires_at IS NOT NULL AND v_expires_at <= now() THEN RETURN 'expired'; END IF;

  IF EXISTS (
    SELECT 1 FROM public.room_members
     WHERE room_id = p_room_id AND user_id = v_uid
  ) THEN
    RETURN 'rejoined';
  END IF;

  IF v_uid <> v_host AND NOT EXISTS (
    SELECT 1 FROM public.room_invitations ri
     WHERE ri.room_id = p_room_id
       AND ri.invitee_id = v_uid
       AND ri.status IN ('pending', 'accepted')
       AND ri.expires_at > now()
  ) THEN
    RETURN 'not_invited';
  END IF;

  SELECT count(*) INTO v_count
    FROM public.room_members
   WHERE room_id = p_room_id;
  IF v_count >= LEAST(COALESCE(v_max, 5), 5) THEN RETURN 'full'; END IF;

  INSERT INTO public.room_members (room_id, user_id)
  VALUES (p_room_id, v_uid)
  ON CONFLICT (room_id, user_id) DO NOTHING;

  UPDATE public.room_invitations
     SET status = 'accepted', accepted_at = COALESCE(accepted_at, now())
   WHERE room_id = p_room_id AND invitee_id = v_uid;

  RETURN 'joined';
END;
$$

CREATE FUNCTION public.enforce_free_room_limits()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.host_user_id IS DISTINCT FROM OLD.host_user_id THEN
    RAISE EXCEPTION 'Room ownership cannot be changed';
  END IF;
  IF NEW.status = 'active' THEN
    PERFORM 1 FROM public.profiles WHERE id=NEW.host_user_id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.study_rooms WHERE host_user_id=NEW.host_user_id
      AND id<>NEW.id AND status='active' AND (expires_at IS NULL OR expires_at>now())) THEN
      RAISE EXCEPTION 'Close your existing room before creating another';
    END IF;
    NEW.max_members := LEAST(GREATEST(COALESCE(NEW.max_members,5),2),5);
    NEW.expires_at := LEAST(COALESCE(NEW.expires_at,now()+interval '6 hours'),now()+interval '6 hours');
  END IF;
  RETURN NEW;
END;
$$

CREATE FUNCTION public.launch_upload_fits(p_user uuid,p_bucket text,p_name text,p_metadata jsonb)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_uid uuid := p_user;
  v_used bigint;
  v_size bigint;
  v_max bigint;
  v_cap bigint;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  CASE p_bucket
    WHEN 'voice-notes' THEN v_max:=10485760; v_cap:=31457280;
    WHEN 'pdfs' THEN v_max:=20971520; v_cap:=104857600;
    WHEN 'office-files' THEN v_max:=52428800; v_cap:=104857600;
    WHEN 'avatars' THEN v_max:=5242880; v_cap:=10485760;
    ELSE RETURN false;
  END CASE;
  -- Serialize concurrent admissions for the same account. Missing size reserves a full file.
  PERFORM 1 FROM public.profiles WHERE id=v_uid FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  v_size:=COALESCE((p_metadata->>'size')::bigint,v_max);
  IF v_size<0 OR v_size>v_max THEN RETURN false; END IF;
  IF p_bucket='voice-notes' AND split_part(p_name,'/',1)='rooms' THEN
    IF NOT EXISTS(SELECT 1 FROM public.room_members rm JOIN public.study_rooms r ON r.id=rm.room_id
      WHERE rm.user_id=v_uid AND rm.room_id::text=split_part(p_name,'/',2)
      AND r.status='active' AND r.expires_at>now()) THEN RETURN false; END IF;
  ELSIF split_part(p_name,'/',1)<>v_uid::text THEN RETURN false;
  END IF;
  -- An upsert cannot take another uploader's room recording.
  IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id=p_bucket AND name=p_name
    AND COALESCE(owner_id,'')<>v_uid::text) THEN RETURN false; END IF;
  SELECT COALESCE(sum(COALESCE((metadata->>'size')::bigint,v_max)),0) INTO v_used
    FROM storage.objects WHERE bucket_id=p_bucket AND name<>p_name
    AND (owner_id=v_uid::text OR split_part(name,'/',1)=v_uid::text);
  RETURN v_used+v_size<=v_cap;
END;
$$

-- Storage permission preflights roll back and completion uses an elevated role.
-- Therefore RLS alone cannot serialize aggregate limits. Enforce again at commit,
-- using the uploader identity written by Storage (never client custom metadata).
-- No object metadata is mutated by this trigger; rejected uploads are cleaned up by Storage.
CREATE FUNCTION public.enforce_launch_storage_limit()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
  IF NEW.bucket_id NOT IN ('voice-notes','pdfs','office-files','avatars') THEN RETURN NEW; END IF;
  -- Trusted administrative uploads have no end-user owner_id.
  IF NEW.owner_id IS NULL OR NEW.owner_id='' THEN RETURN NEW; END IF;
  IF NOT public.launch_upload_fits(NEW.owner_id::uuid,NEW.bucket_id,NEW.name,NEW.metadata) THEN
    RAISE EXCEPTION 'Storage limit reached or upload is not permitted';
  END IF;
  RETURN NEW;
END;
$$
